diff --git a/src/core/trailers.ts b/src/core/trailers.ts
index fea2056..523ed86 100644
--- a/src/core/trailers.ts
+++ b/src/core/trailers.ts
@@ -1,7 +1,40 @@
 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
+export interface CommitInfo {
+  author: {
+    name: string;
+    email: string;
+  };
+  committer: {
+    name: string;
+    email: string;
+  };
+  isSigned: boolean;
+}
+
+export interface TrustedAuthor {
+  name: string;
+  email: string;
+}
+
+export const provenanceOf = (
+  trailers: ReadonlyMap<string, string>,
+  commitInfo: CommitInfo,
+  trustedAuthors: ReadonlyArray<TrustedAuthor> = []
+): Provenance => {
   const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+  const declared = (raw === "authored" || raw === "inherited" || raw === "reconstructed") ? raw : "unknown";
+
+  if (declared !== "authored") {
+    return declared;
+  }
+
+  if (isTrustedAuthor(commitInfo.author, trustedAuthors) || commitInfo.isSigned) {
+    return "authored";
+  }
+
   return "unknown";
 };
+
+const isTrustedAuthor = (author: CommitInfo["author"], trusted: ReadonlyArray<TrustedAuthor>): boolean =>
+  trusted.some(t => t.email === author.email && t.name === author.name);
